/**
 * Typings for the vendored Emscripten `ngspice.js` glue in this directory.
 * The implementation is generated by
 * `build/build-ngspice-wasm.sh`; see `manifest.json` for provenance.
 */

export interface NgspiceFS {
	writeFile(path: string, data: string | Uint8Array): void;
	readFile(path: string, opts?: { encoding?: 'utf8' | 'binary' }): string | Uint8Array;
	unlink(path: string): void;
}

export interface NgspiceModuleOptions {
	wasmBinary?: Uint8Array | ArrayBuffer;
	instantiateWasm?: (
		imports: WebAssembly.Imports,
		success: (instance: WebAssembly.Instance, module: WebAssembly.Module) => void
	) => WebAssembly.Exports | undefined;
	noInitialRun?: boolean;
	print?: (text: string) => void;
	printErr?: (text: string) => void;
	onAbort?: (reason: unknown) => void;
}

export interface NgspiceModule {
	FS: NgspiceFS;
	callMain(args: string[]): number;
	_main(argc: number, argv: number): number;
	_malloc(size: number): number;
	_free(pointer: number): void;
	HEAPU8: Uint8Array;
}

declare const createNgspiceModule: (options?: NgspiceModuleOptions) => Promise<NgspiceModule>;

export default createNgspiceModule;
